sys_script.script:
(function executeRule(current, previous /*null when async*/) {
    try {
        // This rule handles summary inferences (those with no session)
        // When they finish, we need to copy the response to the session

        var response = current.getValue('u_response');
        if (!response) return;

        // Check if this looks like a summary (contains summary indicators)
        if (response.indexOf('summarize') === -1 && response.indexOf('conversation') === -1 && response.indexOf('Summary') === -1) {
            // Not a summary inference, skip
            return;
        }

        gs.info('AIAB: Processing summary inference ' + current.getValue('sys_id'));

        // Find the session this summary is for
        // We look for sessions that have exactly 4, 8, 12, etc. finished inferences
        // and no compacted_summary yet
        var sessionGR = new GlideRecord('u_ai_session');
        sessionGR.addQuery('u_compacted_summary', '');
        sessionGR.orderByDesc('sys_updated_on');
        sessionGR.setLimit(1);
        sessionGR.query();

        if (sessionGR.next()) {
            var sessionId = sessionGR.getUniqueValue();

            // Count inferences to verify
            var countAgg = new GlideAggregate('u_ai_inference');
            countAgg.addQuery('u_ai_session', sessionId);
            countAgg.addQuery('u_state', 'finished');
            countAgg.addAggregate('COUNT');
            countAgg.query();

            var count = 0;
            if (countAgg.next()) {
                count = parseInt(countAgg.getAggregate('COUNT'));
            }

            // Only update if count is multiple of 4
            if (count % 4 === 0) {
                sessionGR.u_compacted_summary = response;
                sessionGR.update();

                gs.info('AIAB: Updated session ' + sessionId + ' compacted_summary with ' + response.substring(0, 100) + '...');
            }
        }

    } catch (error) {
        gs.error('AIAB: Error processing summary inference: ' + error);
    }
})(current, previous);
